#!/usr/bin/env bash
# GENERATED by plugin-cursor/scripts/compose.sh — edit plugin/ then re-compose
# Copyright (c) 2024-2026 H3Tech Inc. All rights reserved. PROPRIETARY.
#
# Hook: FileChanged  (non-blocking) — matchers: pipeline-state.json, .synaptory.yaml
# Purpose: Loop Engineering P4 (epic #75). SessionStart emits watchPaths for
# the pipeline state + project config; when either is edited out-of-band this
# hook validates the state and, on drift, injects a warning so the orchestrator
# re-reads via next_action before transitioning anything on top of a corrupt
# board. The acting half of the #83 event monitor.
#
# Non-blocking and best-effort: any error path exits 0 with no output.

set -u

_HOOK_ROOT="${PLUGIN_ROOT:-$(cd "$(dirname "$0")/.." && pwd)}"
# shellcheck source=lib/resolve-python.sh
source "${_HOOK_ROOT}/hooks/lib/resolve-python.sh" 2>/dev/null || exit 0
_py="${SYNAPTORY_PYTHON:-python3}"

if [ -z "${CLAUDE_PROJECT_DIR:-}" ] || [ ! -d "${CLAUDE_PROJECT_DIR}/.synaptory" ]; then
  exit 0
fi

# Drain stdin (FileChanged envelope); we validate the whole state file rather
# than trusting which path triggered, so the exact envelope shape doesn't matter.
cat >/dev/null 2>&1 || true

DRIFT="${_HOOK_ROOT}/hooks/lib/state_drift.py"
[ -f "$DRIFT" ] || exit 0

RESULT=$("$_py" "$DRIFT" "${CLAUDE_PROJECT_DIR}" 2>/dev/null || printf '')
[ -n "$RESULT" ] || exit 0

# On drift: emit an additionalContext warning (universal FileChanged output
# field), a watch_drift events.jsonl breadcrumb, and best-effort telemetry.
# The Python is a QUOTED heredoc (<<'PY') so the shell performs no expansion —
# the message body contains backticks/markdown that would otherwise trigger
# command substitution. The drift result is passed via env, not stdin.
SYNAPTORY_DRIFT_RESULT="$RESULT" \
  SYNAPTORY_HOOK_LIB="${_HOOK_ROOT}/hooks/lib" \
  SYNAPTORY_PROJECT_DIR="${CLAUDE_PROJECT_DIR}" "$_py" - <<'PY' 2>/dev/null || exit 0
import sys, os, json
sys.path.insert(0, os.environ["SYNAPTORY_HOOK_LIB"])
try:
    r = json.loads(os.environ.get("SYNAPTORY_DRIFT_RESULT") or "{}")
except Exception:
    sys.exit(0)
if r.get("ok") or not r.get("checked"):
    sys.exit(0)  # clean or nothing to check → no notification
problems = r.get("problems") or []
project_dir = os.environ["SYNAPTORY_PROJECT_DIR"]
# Breadcrumb for the events monitor / audit trail.
try:
    from synaptory_logger import emit as _log_emit
    _log_emit("watch_drift", project_dir=project_dir, problems=problems)
except Exception:
    pass
msg = (
    "# ⚠️ Synaptory state/config drift detected\n\n"
    "A watched file (pipeline-state.json or .synaptory.yaml) was edited "
    "out-of-band and is now in a shape the pipeline should not act on:\n\n"
    + "\n".join(f"- {p}" for p in problems)
    + "\n\nDo NOT transition any story until this is resolved. Re-read the "
    "board with `next_action`; if it was a bad hand-edit, restore it via the "
    "tracker CLI / state machine (never edit pipeline-state.json directly) and "
    "fix `.synaptory.yaml` to a valid config."
)
try:
    from hook_io import emit
    emit("FileChanged", additional_context=msg)
except Exception:
    print(json.dumps({"additionalContext": msg}))
PY

# Best-effort telemetry (background, never affects the hook).
if printf '%s' "$RESULT" | grep -q '\"ok\": false\|\"ok\":false'; then
  cli=$("${_HOOK_ROOT}/hooks/_resolve-cli.sh" 2>/dev/null || true)
  if [ -n "$cli" ] && [ -x "$cli" ]; then
    ( "$cli" telemetry activity --kind watch_drift --tool "watch-drift" \
        --summary "pipeline-state.json drift detected out-of-band" >/dev/null 2>&1 ) &
    disown 2>/dev/null || true
  fi
fi

exit 0
